#include <iostream>
#include <set>
using namespace std;

int main() {
    int n, a;
    set<int> k;

    cin >> n;
    for (int i = 0; i < n; i++) {
        cin >> a;
        k.insert(a);
    }

    cout << k.size() << endl;
    for (set<int>::iterator it = k.begin(); it != k.end(); ++it) {
        cout << *it << " ";
    }

    return 0;
}

